import "server-only";
import { z } from "zod";
import raw from "@/sources/content/coverage/product-concepts.json";
import type { ProductConcepts } from "./formulary";

/**
 * RxNorm concept identities per product, for the formulary lookup.
 *
 * Generated by `npm run content:sync` from the pipeline's normalized records,
 * which resolved each product against live RxNav and checked the result
 * against the SPL and NDC. Keyed by slug, the same join key the rest of the
 * app uses. See scripts/sync-label-exports.mjs for why the generic clinical
 * drug is included and the bare ingredient is not.
 *
 * Parsed once at module load: a malformed identity file must fail the build,
 * not resolve to "no concepts" and quietly turn every coverage check into
 * "unable to verify".
 */

const ConceptSchema = z.object({ rxcui: z.string().min(1), name: z.string().nullable() });

const FileSchema = z.object({
  products: z.record(
    z.string(),
    z.object({
      exact: ConceptSchema.extend({ tty: z.string().nullable() }),
      clinicalDrug: z.array(ConceptSchema),
    })
  ),
});

const products = FileSchema.parse(raw).products;

/** The concepts for one product, or null for a slug the sync did not cover. */
export function productConcepts(slug: string): ProductConcepts | null {
  const entry = products[slug];
  if (!entry) return null;
  return {
    exact: { rxcui: entry.exact.rxcui, name: entry.exact.name },
    clinicalDrug: entry.clinicalDrug.map((c) => ({ rxcui: c.rxcui, name: c.name })),
  };
}
